create extension if not exists pgcrypto;
create table public.jobs (id uuid primary key default gen_random_uuid(), reference text not null unique, title text not null, description text not null, criteria jsonb not null default '[]', criteria_version integer not null default 1, approved_at timestamptz, created_at timestamptz not null default now());
create table public.applications (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs(id), form_id text not null, response_id text not null, submitted_at timestamptz not null, candidate jsonb not null, criteria_snapshot jsonb not null, criteria_version integer not null, process_status text not null default 'received' check (process_status in ('received','processing','ready','manual_review','failed')), review_status text not null default 'unreviewed' check (review_status in ('unreviewed','in_review','reviewed')), error_message text, attempt_count integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(form_id,response_id));
create index applications_status_idx on public.applications(process_status,created_at desc);
create table public.documents (id uuid primary key default gen_random_uuid(), application_id uuid not null unique references public.applications(id) on delete cascade, storage_key text not null, mime_type text not null, byte_size integer not null, extracted_text text, extraction_status text not null default 'pending');
create table public.candidate_profiles (application_id uuid primary key references public.applications(id) on delete cascade, normalized jsonb not null, warnings jsonb not null default '[]', model text not null, usage jsonb, created_at timestamptz not null default now());
create table public.evidence_items (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, criterion_id text not null, criterion_version integer not null, status text not null, excerpt text, location text, reasoning text not null, question text, review_mark text not null default 'unreviewed', reviewer_note text, unique(application_id,criterion_id,criterion_version));
create table public.review_actions (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, action_type text not null, author_id uuid not null, notes text, created_at timestamptz not null default now());
create table public.workflow_events (id uuid primary key default gen_random_uuid(), application_id uuid references public.applications(id) on delete cascade, event_type text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.processing_attempts (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, stage text not null, outcome text not null, duration_ms integer, error_category text, created_at timestamptz not null default now());
alter table public.jobs enable row level security;
alter table public.applications enable row level security;
alter table public.documents enable row level security;
alter table public.candidate_profiles enable row level security;
alter table public.evidence_items enable row level security;
alter table public.review_actions enable row level security;
alter table public.workflow_events enable row level security;
alter table public.processing_attempts enable row level security;
revoke all on all tables in schema public from anon, authenticated;
grant usage on schema public to service_role;
grant all on all tables in schema public to service_role;
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('private-cvs','private-cvs',false,3000000,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict (id) do nothing;
